let rankFilters={restaurant:'',department:'',position:'',status:'',period:'all',search:'',sort:'best'};
function rankingRows(users,filters,now=Date.now()){
 return users.map(u=>{const metrics=courseResults(u,activeCourse(),filters.period,now);return {...u,metrics,attempts:metrics.attempts,best:metrics.score,progress:metrics.lessonProgress,status:metrics.status};})
 .filter(u=>(!filters.restaurant||u.restaurantId===filters.restaurant)&&(!filters.department||u.department===filters.department)&&(!filters.position||u.position===filters.position)&&(!filters.status||u.status===filters.status)&&u.name.toLocaleLowerCase('ru').includes(filters.search.trim().toLocaleLowerCase('ru'))&&(filters.period==='all'||u.attempts.length))
 .sort((a,b)=>(filters.sort==='progress'?b.progress-a.progress:filters.sort==='attempts'?a.attempts.length-b.attempts.length:(b.best??-1)-(a.best??-1))||((b.best??-1)-(a.best??-1))||b.progress-a.progress||a.name.localeCompare(b.name,'ru'));
}
function ranking(){
 const target=manager?$('#managerbody'):$('#content');
 const select=(id,label,options)=>`<div class="field"><label for="rank-${id}">${label}</label><select id="rank-${id}" data-rank="${id}">${options.map(([v,n])=>`<option value="${v}" ${rankFilters[id]===v?'selected':''}>${n}</option>`).join('')}</select></div>`;
 target.innerHTML=`${manager?'':'<div class="eyebrow">АКАДЕМИЯ КОМАНДЫ</div><h1>Рейтинг сотрудников</h1><p>Растём вместе. Следи за результатами команды.</p>'}<div class="card"><div class="row"><h2>Рейтинг обучения</h2><button class="btn secondary" id="rank-reset">Сбросить фильтры</button></div><p class="muted">Для перенесённых курсов баллы — сумма лучших подтверждённых результатов каждого теста, взвешенная по числу вопросов; непройденные проверки дают 0. Повторные попытки не добавляют баллы повторно. Ответы на ручной проверке не оцениваются до решения менеджера. Период ограничивает попытки и решения менеджера; материалы показаны за всё время.</p><div class="rankfilters"><div class="field"><label for="rank-search">Поиск сотрудника</label><input id="rank-search" value="${esc(rankFilters.search)}" placeholder="Имя или фамилия" maxlength="80"></div>${select('restaurant','Заведение',[['','Все заведения'],...RESTAURANTS.map(r=>[r.id,r.name])])}${select('department','Подразделение',[['','Все подразделения'],...Object.keys(DEPARTMENTS).map(d=>[d,d])])}${select('position','Должность',[['','Все должности'],...(rankFilters.department?DEPARTMENTS[rankFilters.department]:Object.values(DEPARTMENTS).flat()).map(p=>[p,p])])}${select('status','Результат теста',[['','Все статусы'],['passed','Все тесты пройдены'],['progress','В процессе'],['pending','Ожидает проверки'],['failed','Нужна пересдача'],['none','Без попыток']])}${select('period','Период попыток',[['all','За всё время'],['7','Последние 7 дней'],['30','Последние 30 дней'],['90','Последние 90 дней']])}${select('sort','Сортировка',[['best','Баллы курса ↓'],['progress','Прогресс уроков ↓'],['attempts','Количество попыток ↑']])}</div><div id="rank-results" aria-live="polite"></div></div><div class="note">Демокоманда: ${db.users.filter(u=>u.demo).length} вымышленных сотрудников с отметкой «Демо». Рейтинг основан на данных этого браузера. Без подтверждённого результата сотрудник не получает место. При выборе периода показываются сотрудники с попытками за этот период. Выбранный курс: ${esc(activeCourse().title)}. Результаты разных курсов считаются отдельно.</div>`;
 const update=()=>{const rows=rankingRows(db.users,rankFilters);let place=0;$('#rank-results').innerHTML=`<div class="sectionhead"><span class="muted">Найдено: ${rows.length} из ${db.users.length}</span><span class="tag">${rankFilters.sort==='best'?'По баллам':rankFilters.sort==='progress'?'По прогрессу':'По попыткам'}</span></div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Место*</th><th>Сотрудник</th><th>Подразделение</th><th>Баллы курса</th><th>Материалы</th><th>Проверки</th><th>Попытки</th><th>Результат</th></tr></thead><tbody>${rows.map(u=>`<tr class="${u.id===db.current?'rank-self':''}"><td><span class="rank-place">${u.best===null?'—':++place}</span></td><td>${esc(u.name)} ${u.demo?'<span class="tag">Демо</span>':''} ${u.id===db.current?'<span class="tag">Вы</span>':''}<div class="muted">${esc(u.position)} · ${esc(restaurantName(u.restaurantId))}</div></td><td>${esc(u.department)}</td><td class="${u.best>=80?'success':''}">${u.best===null?'—':u.best+'%'}</td><td>${u.progress}%<div class="muted">${u.metrics.read}/${u.metrics.lessons}</div></td><td>${u.metrics.passedTests}/${u.metrics.testTotal}<div class="muted">${u.metrics.pending?u.metrics.pending+' на проверке':'Пройдено'}</div></td><td>${u.attempts.length}</td><td class="${u.status==='passed'?'success':u.status==='failed'?'danger':'muted'}">${resultStatus(u.status)}</td></tr>`).join('')}</tbody></table></div><p class="muted">* Позиция среди сотрудников с подтверждёнными баллами в выбранной выборке и сортировке.</p>`:'<div class="empty">Нет сотрудников по выбранным фильтрам.<br>Измените условия или выберите «За всё время».</div>'}`;};
 document.querySelectorAll('[data-rank]').forEach(el=>el.onchange=()=>{rankFilters[el.dataset.rank]=el.value;if(el.dataset.rank==='department'){rankFilters.position='';render();return}update()});$('#rank-search').oninput=e=>{rankFilters.search=e.target.value;update()};$('#rank-reset').onclick=()=>{rankFilters={restaurant:'',department:'',position:'',status:'',period:'all',search:'',sort:'best'};render()};update();
}
const originalManagerPage=managerPage;
managerPage=function(){originalManagerPage();const scope=document.createElement('div');scope.className='field';scope.innerHTML=`<label for="manager-restaurant">Команда заведения</label><select id="manager-restaurant"><option value="">Все заведения · деморежим</option>${RESTAURANTS.map(r=>`<option value="${r.id}" ${managerRestaurant===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`;document.querySelector('.tabs').before(scope);document.querySelector('#manager-restaurant').onchange=e=>{managerRestaurant=e.target.value;if(mtab==='ranking')rankFilters.restaurant=managerRestaurant;managerPage()};const tabs=document.querySelector('.tabs');const b=document.createElement('button');b.textContent='Рейтинг';b.className=mtab==='ranking'?'active':'';b.onclick=()=>{mtab='ranking';rankFilters.restaurant=managerRestaurant;managerPage()};tabs.append(b);if(mtab==='ranking')ranking();};
const originalRender=render;
render=function(){originalRender();if(!user())return;
 const nav=document.querySelector('.nav'),bottom=document.querySelector('.bottomnav');
 const add=container=>{const b=document.createElement('button');b.textContent='🏆 Рейтинг';b.className=!manager&&view==='ranking'?'active':'';b.onclick=()=>{manager=false;go('ranking')};container.append(b)};add(nav);add(bottom);
 if(!manager&&view==='ranking'){ranking();const picker=document.createElement('div');picker.className='field';picker.innerHTML=`<label for="ranking-course">Курс рейтинга</label><select id="ranking-course">${db.courses.map(c=>`<option value="${esc(c.id)}" ${c.id===db.selectedCourse?'selected':''}>${esc(c.title)}</option>`).join('')}</select>`;document.querySelector('#content').prepend(picker);document.querySelector('#ranking-course').onchange=e=>selectCourse(e.target.value)}
};
render();
